 exact=(o,keys)=>{if(!o||Array.isArray(o)||Object.keys(o).length!==keys.length||keys.some(k=>!Object.hasOwn(o,k)))fail();},
 hash=x=>typeof x==='string'&&/^[0-9a-f]{64}$/.test(x),
